using TradingSystem.Operations;namespace TradingSystem.Operations.Tests;public sealed class OperationalContractTests{[Fact]public void Deduplication_key_should_keep_alert_identity_stable(){var a=new AlertCandidate("operational:heartbeat:StrategyService:one",AlertSeverity.Critical,"ServiceHeartbeatMissing","stale");Assert.StartsWith("operational:",a.DeduplicationKey);}[Fact]public void Heartbeat_should_have_stale_threshold(){var h=new ServiceHeartbeat("StrategyService","one","1.0","Demo",OperationalStatus.Healthy,DateTime.UtcNow,DateTime.UtcNow,30);Assert.True(h.StaleAfterSeconds>0);}}